FUNCTION_BLOCK FB
VAR_INPUT
 mode : INT;
 resetBtn : BOOL;
 scanSeconds : REAL;
 tempSP : REAL;
 tempPV : REAL;
 flowPV : REAL;
 manualFlowSP : REAL;
 manualValve : REAL;
END_VAR
VAR_OUTPUT
 flowSP : REAL;
 valveCommand : REAL;
 fault : BOOL;
 normalMode : BOOL;
END_VAR
VAR
 firstScan : BOOL := TRUE;
 prevMode : INT := 0;
 prevResetBtn : BOOL := FALSE;
 prevFlowSP : REAL := 0.0;
 prevValveCommand : REAL := 0.0;
 prevET : REAL := 0.0;
 prevEF : REAL := 0.0;
 resetRising : BOOL;
 modeChanged : BOOL;
 eT : REAL;
 eF : REAL;
 trialT : REAL;
 trialF : REAL;
END_VAR

BEGIN
 fault := (mode < 0) OR (mode > 2) OR (scanSeconds <= 0.0) OR (scanSeconds > 10.0);
 resetRising := resetBtn AND NOT prevResetBtn;
 modeChanged := (NOT firstScan) AND (mode <> prevMode);
 normalMode := (NOT firstScan) AND (mode = prevMode) AND NOT fault AND NOT resetRising;

 eT := tempSP - tempPV;
 eF := flowSP - flowPV; // But eF current depends on flowSP, which not yet computed unless holding? For normal, need compute flowSP first then eF. For switch/manual outputs known prescriptively, we can compute eF after flowSP assigned. Better structure branch and after branch update prevEF.

